set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
test -z "$(squeue -h --name=cosearch-local-five -o '%i')"
test ! -d "$R/runs/cosearch-local-five-20261003-b"
test ! -f "$R/logs/local-five-b.queued"
base64 -d > "$R/tools/five_iteration_job_b.py" <<'PYCODE'

PYCODE
tmux new-session -d -s cosearch-local-five-b-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five '$R/env/bin/python' '$R/tools/five_iteration_job_b.py' > '$R/logs/local-five-b.log' 2>&1"
touch "$R/logs/local-five-b.queued"
